// 🎲 Generar usuario aleatorio y guardarlo en variables de colección
const randomUsername = pm.collectionVariables.replaceIn('{{$randomUserName}}');
const randomPassword = "Test" + pm.collectionVariables.replaceIn('{{$randomInt}}') + "Abc!";

pm.collectionVariables.set("uniqueUser", randomUsername);
pm.collectionVariables.set("uniquePassword", randomPassword);

// Actualizar el body del request con los valores generados
pm.request.body.update({
    mode: "formdata",
    formdata: [
        { key: "username", value: randomUsername, type: "text" },
        { key: "password", value: randomPassword, type: "text" },
        { key: "confirmPassword", value: randomPassword, type: "text" }
    ]
});

// ✅ Caso exitoso: registro correcto
pm.test("Status 200 o 201 en registro exitoso", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

pm.test("Respuesta contiene token o mensaje de éxito", function () {
    const res = pm.response.json();
    pm.expect(res).to.satisfy(r => r.token || r.message || r.user || r._id);
});

pm.test("La respuesta es un objeto JSON válido", function () {
    pm.response.to.be.json;
});

pm.test("Username cumple mínimo 3 caracteres", function () {
    const username = pm.collectionVariables.get("uniqueUser");
    pm.expect(username.length).to.be.at.least(3);
});

pm.test("Password cumple el patrón requerido", function () {
    const password = pm.collectionVariables.get("uniquePassword");
    const pattern = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?])/;
    pm.expect(pattern.test(password)).to.be.true;
});

pm.test("confirmPassword coincide con password (ambas variables iguales)", function () {
    const password = pm.collectionVariables.get("uniquePassword");
    pm.expect(password).to.be.a("string").and.not.empty;
});

pm.test("Variables uniqueUser y uniquePassword fueron guardadas", function () {
    pm.expect(pm.collectionVariables.get("uniqueUser")).to.be.a("string").and.not.empty;
    pm.expect(pm.collectionVariables.get("uniquePassword")).to.be.a("string").and.not.empty;
});

// ❌ CASOS NEGATIVOS - register
pm.test("[NEG] Si el status es 400, la respuesta contiene mensaje de error", function () {
    if (pm.response.code === 400) {
        const res = pm.response.json();
        pm.expect(res).to.satisfy(r => r.message || r.error || r.errors);
    }
});

pm.test("[NEG] Si el status es 400 por username corto, el mensaje lo indica", function () {
    if (pm.response.code === 400) {
        const res = pm.response.json();
        const msg = JSON.stringify(res).toLowerCase();
